const SENDER_REF = "gmail:g2-team-test-sender";
// Workflow B, node "Validate send request". Only the job ID and workspace are used. Anything
// else in the payload (subject, body, recipient, approved: true, ...) is ignored and reported:
// the email, recipient and approval are read from the database by the claim functions.
// SENDER_REF (prepended by build_workflows.py) names the Gmail credential this workflow sends
// with; the approval binds it, so changing the sender requires a new approval.
const b = $input.first().json.body ?? {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const WS = /^[a-z0-9][a-z0-9_-]{0,62}$/;
const reasons = [];
if (!UUID.test(String(b.job_id ?? ''))) reasons.push('job_id must be a UUID');
if (!WS.test(String(b.workspace_id ?? ''))) reasons.push('workspace_id missing or invalid');
const ignored = Object.keys(b).filter(k => !['job_id', 'workspace_id'].includes(k));
return [{ json: { valid: reasons.length === 0, reasons, job_id: String(b.job_id ?? ''),
  workspace_id: String(b.workspace_id ?? ''), sender_ref: SENDER_REF, ignored_fields: ignored,
  response: { job_id: b.job_id ?? null, status: 'invalid_request', reasons, source: 'n8n' } } }];

// Workflow B, node "Check claim". Input: g2_ai_v1.claim_send_job(). Only a claimed job goes on;
// already finished, in progress, refused or unknown jobs are answered from the database.
const v = $('Validate send request').first().json;
const r = $input.first().json.r ?? {};
if (r.status !== 'claimed') {
  return [{ json: { route: 'respond', response: { job_id: v.job_id, status: r.status ?? 'error',
    job_status: r.job_status ?? null, reason: r.reason ?? null, provider_message_id: r.provider_message_id ?? null,
    detail: r.detail ?? null, ignored_fields: v.ignored_fields, source: 'database' } } }];
}
return [{ json: { route: 'dispatch', job_id: v.job_id, workspace_id: v.workspace_id,
  lease_token: r.lease_token, delivery_mode: r.delivery_mode, ignored_fields: v.ignored_fields } }];

// Workflow B, node "Check dispatch". Input: g2_ai_v1.begin_dispatch(): the job is now
// 'dispatching' (committed) and r holds the approved email read from the database.
// Routes: respond (refused before dispatch), finish (known failure, nothing sent), mock, gmail.
const c = $('Check claim').first().json;
const r = $input.first().json.r ?? {};
const base = { job_id: c.job_id, lease_token: c.lease_token };
if (r.ok !== true) {
  return [{ json: { ...base, route: 'respond', response: { job_id: c.job_id, status: 'refused',
    job_status: r.job_status ?? null, reason: r.reason ?? null, source: 'database' } } }];
}
const problems = [];
if (!String(r.subject ?? '').startsWith('[DEMO] ')) problems.push('subject lacks the [DEMO] prefix');
if (!String(r.body ?? '').includes('DEMO')) problems.push('body lacks the DEMO notice');
if (r.delivery_mode === 'team_test_email' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(r.to ?? ''))) {
  problems.push('recipient address invalid');
}
if (problems.length) {
  return [{ json: { ...base, route: 'finish', outcome: 'failed', provider_message_id: null,
    detail: 'Not sent: ' + problems.join('; ') } }];
}
return [{ json: { ...base, route: r.delivery_mode === 'mock' ? 'mock' : 'gmail', to: r.to,
  subject: r.subject, body: r.body, content_hash: r.content_hash } }];

// Workflow B, node "Simulate send (no email)": delivery_mode mock. Nothing leaves n8n.
const d = $input.first().json;
const run = typeof $execution !== 'undefined' && $execution?.id ? String($execution.id) : 'run';
return [{ json: { job_id: d.job_id, lease_token: d.lease_token, outcome: 'simulated',
  provider_message_id: `n8n-mock-${String(d.job_id).slice(0, 8)}-${run}`,
  detail: 'Simulated by n8n workflow B: no email sent' } }];

const GMAIL_BRANCH = "ok";
// Workflow B, nodes "Gmail accepted" / "Gmail error" (GMAIL_BRANCH prepended: 'ok' | 'error').
// Gmail returned a message ID -> provider_accepted (the provider took it; delivery to the inbox
// is confirmed only by a tester). An error that proves Gmail refused before sending (auth /
// credential / invalid recipient, HTTP 400/401/403) -> failed. Anything else (timeout, 5xx,
// network) -> unknown: the email may have left, so it is never resent automatically.
const d = $('Check dispatch').first().json;
const j = $input.first().json;
let outcome, id = null, detail;
if (GMAIL_BRANCH === 'ok') {
  id = j.id ?? j.messageId ?? null;
  outcome = id ? 'provider_accepted' : 'unknown';
  detail = id ? 'Accepted by Gmail (receipt not verified yet)' : 'Gmail answered without a message ID';
} else {
  const msg = String(j.error?.message ?? j.error?.description ?? j.error ?? j.message ?? 'Gmail error');
  const code = Number(j.error?.httpCode ?? j.error?.status ?? j.error?.statusCode ?? NaN);
  const refused = [400, 401, 403].includes(code) ||
    /invalid_grant|unauthori[sz]ed|credential|invalid to header|invalid recipient|forbidden|status code (400|401|403)(?!\d)/i.test(msg);
  outcome = refused ? 'failed' : 'unknown';
  detail = (refused ? 'Gmail refused before sending: ' : 'Gmail result unknown (may have been sent): ') + msg.slice(0, 400);
}
return [{ json: { job_id: d.job_id, lease_token: d.lease_token, outcome, provider_message_id: id, detail } }];

const GMAIL_BRANCH = "error";
// Workflow B, nodes "Gmail accepted" / "Gmail error" (GMAIL_BRANCH prepended: 'ok' | 'error').
// Gmail returned a message ID -> provider_accepted (the provider took it; delivery to the inbox
// is confirmed only by a tester). An error that proves Gmail refused before sending (auth /
// credential / invalid recipient, HTTP 400/401/403) -> failed. Anything else (timeout, 5xx,
// network) -> unknown: the email may have left, so it is never resent automatically.
const d = $('Check dispatch').first().json;
const j = $input.first().json;
let outcome, id = null, detail;
if (GMAIL_BRANCH === 'ok') {
  id = j.id ?? j.messageId ?? null;
  outcome = id ? 'provider_accepted' : 'unknown';
  detail = id ? 'Accepted by Gmail (receipt not verified yet)' : 'Gmail answered without a message ID';
} else {
  const msg = String(j.error?.message ?? j.error?.description ?? j.error ?? j.message ?? 'Gmail error');
  const code = Number(j.error?.httpCode ?? j.error?.status ?? j.error?.statusCode ?? NaN);
  const refused = [400, 401, 403].includes(code) ||
    /invalid_grant|unauthori[sz]ed|credential|invalid to header|invalid recipient|forbidden|status code (400|401|403)(?!\d)/i.test(msg);
  outcome = refused ? 'failed' : 'unknown';
  detail = (refused ? 'Gmail refused before sending: ' : 'Gmail result unknown (may have been sent): ') + msg.slice(0, 400);
}
return [{ json: { job_id: d.job_id, lease_token: d.lease_token, outcome, provider_message_id: id, detail } }];

// Workflow B, node "Send result response": what finish_dispatch() stored (Streamlit reads the
// database by job ID anyway). If storing failed, the job stays 'dispatching' and becomes
// 'unknown' after 5 minutes: it is reconciled, never resent.
const r = $input.first().json.r ?? {};
const c = $('Check claim').first().json;
return [{ json: { job_id: c.job_id, status: r.stored === true ? 'stored' : 'not_stored',
  job_status: r.job_status ?? null, provider_message_id: r.provider_message_id ?? null,
  detail: r.detail ?? r.reason ?? null, ignored_fields: c.ignored_fields ?? [], source: 'database' } }];
